def run(value_list):
    """
    Calculates the difference between the domestic and international discount rates as at September 30, 2019.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a financial report value.

    Returns:
        A tuple (number, scale).
    """
    domestic_rate = None
    international_rate = None

    for item in value_list:
        if item['header1'] == '2019' and item['header2'] == 'September 30,' and item['header3'] == 'Domestic' and item['category'] == 'Discount rate':
            domestic_rate = float(item['number_value'])
        if item['header1'] == '2019' and item['header2'] == 'September 30,' and item['header3'] == 'International' and item['category'] == 'Discount rate':
            international_rate = float(item['number_value'])

    if domestic_rate is not None and international_rate is not None:
        difference = international_rate - domestic_rate
        return (round(difference, 2), '%')
    else:
        return (None, None)

def run(value_list):
    """
    Calculates the year on year percentage change in domestic discount rate between 2018 and 2019.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a financial value.

    Returns:
        A tuple (number, scale).
    """
    domestic_2018 = None
    domestic_2019 = None

    for item in value_list:
        if item['category'] == 'Discount rate' and item['header3'] == 'Domestic':
            if item['header1'] == '2018':
                domestic_2018 = item['number_value']
            elif item['header1'] == '2019':
                domestic_2019 = item['number_value']

    if domestic_2018 is not None and domestic_2019 is not None:
        percentage_change = ((domestic_2019 - domestic_2018) / domestic_2018) * 100
        return (round(percentage_change, 2), 'percent')
    else:
        return (None, None)

def run(value_list):
    """
    Calculates the year on year percentage change in international expected return on plan assets between 2018 and 2019.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a financial value.

    Returns:
        A tuple (number, scale).
    """

    year_2018_value = next((item for item in value_list if item['header1'] == '2018' and item['category'] == 'Expected return on plan assets' and item['header3'] == 'International'), None)
    year_2019_value = next((item for item in value_list if item['header1'] == '2019' and item['category'] == 'Expected return on plan assets' and item['header3'] == 'International'), None)

    if year_2018_value and year_2019_value:
        change = year_2019_value['number_value'] - year_2018_value['number_value']
        percentage_change = (change / year_2018_value['number_value']) * 100
        return (round(percentage_change, 2), 'percent')
    else:
        return (None, None)

