def run(value_list):
    """
    Calculates the percentage change in Value added tax receivables, net, noncurrent in 2019 from 2018.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a financial value.

    Returns:
        A tuple (number, scale).
    """
    try:
        # Extract values for 2019 and 2018
        value_2019 = next((item['number_value'] for item in value_list if item['header1'] == '2019' and item['category'] == 'Value added tax receivables, net, noncurrent'), None)
        value_2018 = next((item['number_value'] for item in value_list if item['header1'] == '2018' and item['category'] == 'Value added tax receivables, net, noncurrent'), None)

        if value_2018 is None or value_2019 is None:
            return (0.00, "")

        # Calculate the percentage change
        percentage_change = ((value_2019 - value_2018) / value_2018) * 100

        return (round(percentage_change, 2), "")

    except (TypeError, ValueError):
        return (0.00, "")

