def run(value_list):
    data = {}
    for item in value_list:
        category = item['category']
        year = item['header1']
        value = item['number_value']
        scale = item['scale']

        if category == 'State and local income tax rate, net of federal tax benefits':
            if year not in data:
                data[year] = {'value': value, 'scale': scale}
            else:
                data[year]['value'] = (data[year]['value'] + value) / 2
                data[year]['scale'] = data[year]['scale']

    result = []
    for year in ['2017', '2018', '2019']:
        if year in data:
            result.append((data[year]['value'], data[year]['scale']))

    if not result:
        return (0.00, '')

    total = 0
    for value, scale in result:
        total += value

    average = total / len(result)

    return (round(average, 2), result[0][1])

