def run(value_list):
    """
    Calculates the average net income for 2018 and 2019 from the provided financial report.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a financial value.

    Returns:
        A tuple containing the average net income and its scale.
    """
    net_income_2018 = []
    net_income_2019 = []

    for item in value_list:
        if item['category'] == 'Net Income' and item['header1'] == 'April 28, 2018':
            net_income_2018.append(float(item['number_value']))
        elif item['category'] == 'Net Income' and item['header1'] == 'April 27, 2019':
            net_income_2019.append(float(item['number_value']))

    if net_income_2018:
        avg_net_income_2018 = sum(net_income_2018) / len(net_income_2018)
    else:
        avg_net_income_2018 = 0.0

    if net_income_2019:
        avg_net_income_2019 = sum(net_income_2019) / len(net_income_2019)
    else:
        avg_net_income_2019 = 0.0

    average_net_income = (avg_net_income_2018 + avg_net_income_2019) / 2

    return (round(average_net_income, 2), 'million')

