def run(value_list):
    """
    Calculates the average dividend yield in 2018 and 2019.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple (number, scale).
    """

    year_2018_values = [d for d in value_list if d['header1'] == '2018']
    year_2019_values = [d for d in value_list if d['header1'] == '2019']

    if not year_2018_values or not year_2019_values:
        return (0.00, "")

    dividend_yield_2018 = [d['number_value'] for d in year_2018_values if d['category'] == 'Dividend yield']
    dividend_yield_2019 = [d['number_value'] for d in year_2019_values if d['category'] == 'Dividend yield']

