    Calculates the average Services for 2018 and 2019 from the provided list.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple (number, scale) representing the average Services for 2018 and 2019.
    """

    service_2018 = 0
    service_2019 = 0

    for item in value_list:
        if item['category'] == 'Cost of services revenue':
            if item['header4'] == '2018':
                service_2018 = item['number_value']
            elif item['header4'] == '2019':
                service_2019 = item['number_value']

    if service_2018 == 0 or service_2019 == 0:
        return (0.00, "")

    average_services = (service_2018 + service_2019) / 2
    return (round(average_services, 2), item['scale'])

def run(value_list):
    """
    Calculates the average total cost of revenue for 2018 and 2019.

    Args:
