def run(value_list):
    """
    Calculates the percentage change in total assets between 2015 and 2016.

    Args:
        value_list: A list of dictionaries, where each dictionary represents
                    a financial value with 'number_value' and 'category' keys.

    Returns:
        A tuple (number, scale). The number is a float with accuracy to two
        decimal places, and the scale is a string (e.g., '', 'thousand',
        'million', 'billion', 'percent').
    """
    assets_2015 = None
    assets_2016 = None

    for item in value_list:
        if item['category'] == 'Total assets' and item['header1'] == '2015':
            assets_2015 = item['number_value']
        elif item['category'] == 'Total assets' and item['header1'] == '2016':
            assets_2016 = item['number_value']

    if assets_2015 is not None and assets_2016 is not None:
        percentage_change = ((assets_2016 - assets_2015) / assets_2015) * 100
        return (round(percentage_change, 2), '')
    else:
        return (None, None)

