def run(value_list):
    """
    Calculates the percentage of the total unrealized gain generated from U.S. government obligations in 2018.

    Args:
        value_list: A list of dictionaries containing financial report data.

    Returns:
        A tuple (number, scale).
    """
    us_government_gains_2018 = 0
    total_gains_2018 = 0

    for item in value_list:
        if item['category'] == 'U.S. government obligations' and item['header3'] == 'As of December 31, 2018':
            if 'Gains' in item:
                us_government_gains_2018 += item['number_value']
            elif 'Losses' in item:
                us_government_gains_2018 -= item['number_value']
        if 'Total' in item and item['header3'] == 'As of December 31, 2018':
            if 'Gains' in item:
                total_gains_2018 += item['number_value']

    if total_gains_2018 == 0:
        return (0.00, "")

    percentage = (us_government_gains_2018 / total_gains_2018) * 100
    return (round(percentage, 2), "")

def run(value_list):
    total_amortized_cost_2018 = 0.0
    foreign_government_obligations_amortized_2018 = 0.0

    for item in value_list:
        if item['header3'] == 'As of December 31, 2018':
            if item['category'] == 'Total':
                if item['header1'] == 'Cost':
                    total_amortized_cost_2018 += item['number_value']
                elif item['header1'] == 'Value':
                    total_amortized_cost_2018 += item['number_value']
                elif item['header1'] == 'Gains':
                    total_amortized_cost_2018 += item['number_value']
                elif item['header1'] == 'Losses':
                    total_amortized_cost_2018 += item['number_value']
            else:
                if item['category'] == 'Foreign government obligations':
                    if item['header1'] == 'Cost':
                        foreign_government_obligations_amortized_2018 += item['number_value']
                    elif item['header1'] == 'Value':
                        foreign_government_obligations_amortized_2018 += item['number_value']
                    elif item['header1'] == 'Gains':
                        foreign_government_obligations_amortized_2018 += item['number_value']
                    elif item['header1'] == 'Losses':
                        foreign_government_obligations_amortized_2018 += item['number_value']

    if total_amortized_cost_2018 == 0:
        return (0.00, "")

    percentage = (foreign_government_obligations_amortized_2018 / total_amortized_cost_2018) * 100
    return (round(percentage, 2), "")

