def run(value_list):
    """
    Calculates the percentage change in Acquisition and integration costs
    in 2019 from 2018 based on the provided financial report.

    Args:
        value_list: A list of dictionaries, where each dictionary represents
                    a financial value with keys like 'number_value', 'scale',
                    'category', etc.

    Returns:
        A tuple (number, scale). The number is a float with accuracy to two
        decimal places, and the scale is a string.
    """

    # Extract values for 2019 and 2018
    try:
        cost_2019 = next(item['number_value'] for item in value_list if item['category'] == 'Acquisition and integration costs' and item['header3'] == '2019')
        cost_2018 = next(item['number_value'] for item in value_list if item['category'] == 'Acquisition and integration costs' and item['header3'] == '2018')
    except StopIteration:
        return (0.00, "")

    # Calculate the percentage change
    try:
        percentage_change = ((cost_2019 - cost_2018) / cost_2018) * 100
    except ZeroDivisionError:
        return (0.00, "")

    return (round(percentage_change, 2), "percent")

