def run(value_list):
    """
    Calculates the change in Accrued pension liabilities in 2019 from 2018.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple (number, scale).
    """
    try:
        # Extract values for 2019 and 2018
        current_year_value = next(
            (item['number_value'] for item in value_list if item['header1'] == '2019' and item['category'] == 'Accrued pension liabilities'),
            None
        )
        previous_year_value = next(
            (item['number_value'] for item in value_list if item['header1'] == '2018' and item['category'] == 'Accrued pension liabilities'),
            None
        )

        if current_year_value is None or previous_year_value is None:
            return (0.00, "")

        # Calculate the change
        change = current_year_value - previous_year_value

        # Format the result
        return (round(change, 2), "")

    except StopIteration:
        return (0.00, "")

def run(value_list):
