        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple (number, scale).
    """
    try:
        cost_revenue_2019 = float(value_list[0]['number_value'])
        cost_revenue_2018 = float(value_list[1]['number_value'])
        change = cost_revenue_2019 - cost_revenue_2018
        scale = ''
        if abs(change) >= 1000000:
            scale = 'million'
        elif abs(change) >= 100000:
            scale = 'thousand'
        elif abs(change) >= 10000:
            scale = 'hundred thousand'
        elif abs(change) >= 1000:
            scale = 'ten thousand'
        elif abs(change) >= 1000:
            scale = 'hundred'
        elif abs(change) >= 100:
            scale = 'ten'
        elif abs(change) >= 10:
            scale = 'hundred'
        elif abs(change) >= 1:
            scale = 'ten'

        return (round(change, 2), scale)
    except (KeyError, ValueError):
        return (None, None)

