def run(value_list):
    """
    Calculates the percentage change in trade receivables and contract assets
    from 2018 to 2019 based on the provided financial report.

    Args:
        value_list: A list of dictionaries, where each dictionary represents
                    a financial value with keys like 'number_value', 'scale',
                    'category', 'header1', and 'header2'.

    Returns:
        A tuple (number, scale) representing the percentage change,
        rounded to two decimal places.
    """

    # Extract values for 2019 and 2018
    try:
        value_2019 = next(item for item in value_list if item['category'] == 'Trade receivables and contract assets' and item['header1'] == '2019 $thousand')
        value_2018 = next(item for item in value_list if item['category'] == 'Trade receivables and contract assets' and item['header1'] == '2018 $thousand')
    except StopIteration:
        return (0.00, "")

    value_2019_num = value_2019['number_value']
    value_2018_num = value_2018['number_value']

    # Calculate the percentage change
    try:
        percentage_change = ((value_2019_num - value_2018_num) / value_2018_num) * 100
    except ZeroDivisionError:
        return (0.00, "")

    return (round(percentage_change, 2), "percent")

