        A tuple (number, scale).
    """
    total_long_term_debt = 0.0
    long_term_debt_5_years = 0.0

    for item in value_list:
        if item['category'] == 'Long-term debt .':
            if 'number_value' in item and 'header1' in item and item['header1'] == 'Total':
                total_long_term_debt = float(item['number_value'])
                if 'header1' in item and item['header1'] == '1-3 Years':
                    long_term_debt_5_years += float(item['number_value'])

                if 'header1' in item and item['header1'] == '3-5 Years':
                    long_term_debt_5_years += float(item['number_value'])

                if 'header1' in item and item['header1'] == 'After 5 Years':
                    long_term_debt_5_years += float(item['number_value'])

    if total_long_term_debt == 0:
        return (0.00, "")

    proportion = (long_term_debt_5_years / total_long_term_debt) * 100
    return (round(proportion, 2), "percent")

def run(value_list):
    """
    Calculates the ratio of total notes payable to total capital lease obligations.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple (number, scale).
    """
    total_notes_payable = 0
    total_capital_lease_obligations = 0

    for item in value_list:
        if item['category'] == 'Notes payable':
            if 'number_value' in item and 'scale' in item:
                total_notes_payable += float(item['number_value'])
        if item['category'] == 'Capital lease obligations':
            if 'number_value' in item and 'scale' in item:
                total_capital_lease_obligations += float(item['number_value'])

    if total_capital_lease_obligations == 0:
        return (0.00, "")

    ratio = (total_notes_payable / total_capital_lease_obligations) * 100
    return (round(ratio, 2), "percent")

