def run(value_list):
    """
    Calculates the percentage increase/decrease in the total from 2018 to 2019.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a financial value.

    Returns:
        A tuple (number, scale).
    """
    total_2018 = None
    total_2019 = None

    for item in value_list:
        if item['category'] == 'Total' and item['header1'] == '2018':
            total_2018 = item['number_value']
        elif item['category'] == 'Total' and item['header1'] == '2019':
            total_2019 = item['number_value']

    if total_2018 is not None and total_2019 is not None:
        percentage_change = ((total_2019 - total_2018) / total_2018) * 100
        return (round(percentage_change, 2), '')
    else:
        return (None, '')

def run(value_list):
    """
    Calculates the percentage of non-vested shares granted in 2019 as a percentage of the total non-vested shares at December 31, 2019.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a financial report value.

    Returns:
        A tuple (number, scale).
    """

    # Extract relevant data
    granted_shares_2019 = 0
    for item in value_list:
        if item['category'] == 'Granted' and item['header1'] == 'Shares' and item['header2'] == 'Non-vested awards':
            granted_shares_2019 = item['number_value']
            break

    non_vested_shares_2019 = 0
    for item in value_list:
        if item['category'] == 'Non-vested at December 31, 2019' and item['header1'] == 'Shares' and item['header2'] == 'Non-vested awards':
            non_vested_shares_2019 = item['number_value']
            break

    # Calculate the percentage
    if non_vested_shares_2019 == 0:
        return (0.00, "")
    percentage = (granted_shares_2019 / non_vested_shares_2019) * 100

    return (round(percentage, 2), "")

